import React, { useState } from 'react';
import { 
  TrendingUp, 
  CheckCircle, 
  XCircle, 
  AlertCircle, 
  Target,
  BookOpen,
  Lightbulb,
  Clock,
  Star,
  Award,
  TrendingDown,
  Users,
  Code,
  GraduationCap,
  ArrowRight,
  ChevronDown,
  ChevronUp
} from 'lucide-react';

const Results = ({ results }) => {
  const [expandedSections, setExpandedSections] = useState({
    analysis: false,
    learning: false,
    experience: false,
    recommendations: false
  });

  const {
    match_score,
    matched_skills,
    missing_skills,
    resume_skills,
    jd_skills,
    detailed_analysis
  } = results;

  const toggleSection = (section) => {
    setExpandedSections(prev => ({
      ...prev,
      [section]: !prev[section]
    }));
  };

  const getScoreColor = (score) => {
    if (score >= 80) return 'text-success-600';
    if (score >= 60) return 'text-warning-600';
    return 'text-danger-600';
  };

  const getScoreBgColor = (score) => {
    if (score >= 80) return 'bg-success-100';
    if (score >= 60) return 'bg-warning-100';
    return 'bg-danger-100';
  };

  const getScoreMessage = (score) => {
    if (score >= 80) return 'Excellent Match!';
    if (score >= 60) return 'Good Match';
    if (score >= 40) return 'Moderate Match';
    return 'Low Match';
  };

  const getScoreIcon = (score) => {
    if (score >= 60) return <CheckCircle className="w-6 h-6" />;
    return <AlertCircle className="w-6 h-6" />;
  };

  const getPriorityColor = (priority) => {
    switch(priority) {
      case 'high': return 'text-danger-600 bg-danger-50 border-danger-200';
      case 'medium': return 'text-warning-600 bg-warning-50 border-warning-200';
      case 'low': return 'text-success-600 bg-success-50 border-success-200';
      default: return 'text-gray-600 bg-gray-50 border-gray-200';
    }
  };

  const renderLowScoreAnalysis = () => {
    if (!detailed_analysis?.low_score_reasons?.length) return null;

    return (
      <div className="card border-l-4 border-danger-500 mb-6">
        <div className="flex items-center justify-between cursor-pointer" onClick={() => toggleSection('analysis')}>
          <h3 className="text-lg font-semibold flex items-center text-danger-700">
            <TrendingDown className="w-5 h-5 mr-2" />
            Why Your Score is Low
          </h3>
          {expandedSections.analysis ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
        </div>

        {expandedSections.analysis && (
          <div className="mt-4 space-y-2">
            {detailed_analysis.low_score_reasons.map((reason, index) => (
              <div key={index} className="flex items-start">
                <div className="w-2 h-2 bg-danger-500 rounded-full mt-2 mr-3 flex-shrink-0" />
                <span className="text-gray-700">{reason}</span>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  const renderSkillGapAnalysis = () => {
    if (!detailed_analysis?.skill_gap_analysis) return null;

    const { skill_gap_analysis } = detailed_analysis;

    return (
      <div className="grid md:grid-cols-2 gap-6 mb-6">
        <div className="card">
          <h3 className="text-lg font-semibold mb-4 flex items-center">
            <Target className="w-5 h-5 mr-2 text-primary-600" />
            Skill Gap Analysis
          </h3>

          <div className="space-y-3">
            <div className="flex justify-between">
              <span className="text-gray-600">Skills Missing</span>
              <span className="font-medium">{skill_gap_analysis.missing_skills_count} / {skill_gap_analysis.required_skills_count}</span>
            </div>

            <div className="flex justify-between">
              <span className="text-gray-600">Gap Percentage</span>
              <span className={`font-medium ${getScoreColor(100 - skill_gap_analysis.gap_percentage)}`}>
                {skill_gap_analysis.gap_percentage}%
              </span>
            </div>

            <div className="w-full bg-gray-200 rounded-full h-2">
              <div 
                className="bg-danger-500 h-2 rounded-full transition-all duration-1000"
                style={{ width: `${skill_gap_analysis.gap_percentage}%` }}
              />
            </div>
          </div>
        </div>

        <div className="card">
          <h3 className="text-lg font-semibold mb-4 flex items-center">
            <Star className="w-5 h-5 mr-2 text-warning-600" />
            Critical Skills Missing
          </h3>

          {skill_gap_analysis.critical_missing?.length > 0 ? (
            <div className="space-y-2">
              {skill_gap_analysis.critical_missing.map((skill, index) => (
                <div key={index} className="flex items-center justify-between p-2 bg-warning-50 rounded-lg">
                  <span className="font-medium text-warning-800">{skill}</span>
                  <span className="text-xs text-warning-600">Critical</span>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-gray-500">No critical skills missing</p>
          )}
        </div>
      </div>
    );
  };

  const renderImprovementRecommendations = () => {
    if (!detailed_analysis?.improvement_recommendations?.length) return null;

    return (
      <div className="card mb-6">
        <div className="flex items-center justify-between cursor-pointer" onClick={() => toggleSection('recommendations')}>
          <h3 className="text-lg font-semibold flex items-center text-primary-700">
            <Lightbulb className="w-5 h-5 mr-2" />
            Improvement Recommendations
          </h3>
          {expandedSections.recommendations ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
        </div>

        {expandedSections.recommendations && (
          <div className="mt-4 space-y-4">
            {detailed_analysis.improvement_recommendations.map((rec, index) => (
              <div key={index} className={`border rounded-lg p-4 ${getPriorityColor(rec.priority)}`}>
                <div className="flex items-center justify-between mb-2">
                  <h4 className="font-semibold">{rec.category}</h4>
                  <span className="text-xs font-medium uppercase px-2 py-1 rounded">
                    {rec.priority}
                  </span>
                </div>
                <ul className="space-y-1">
                  {rec.items.map((item, itemIndex) => (
                    <li key={itemIndex} className="flex items-start">
                      <ArrowRight className="w-4 h-4 mr-2 mt-0.5 flex-shrink-0" />
                      <span className="text-sm">{item}</span>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  const renderLearningPaths = () => {
    if (!detailed_analysis?.learning_paths?.length) return null;

    return (
      <div className="card mb-6">
        <div className="flex items-center justify-between cursor-pointer" onClick={() => toggleSection('learning')}>
          <h3 className="text-lg font-semibold flex items-center text-primary-700">
            <GraduationCap className="w-5 h-5 mr-2" />
            Learning Paths
          </h3>
          {expandedSections.learning ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
        </div>

        {expandedSections.learning && (
          <div className="mt-4 space-y-4">
            {detailed_analysis.learning_paths.map((path, index) => (
              <div key={index} className="border rounded-lg p-4">
                <div className="flex items-center justify-between mb-3">
                  <h4 className="font-semibold text-lg">{path.skill}</h4>
                  <div className="flex items-center space-x-2 text-sm">
                    <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded">
                      {path.difficulty}
                    </span>
                    <span className="px-2 py-1 bg-green-100 text-green-700 rounded flex items-center">
                      <Clock className="w-3 h-3 mr-1" />
                      {path.time_estimate}
                    </span>
                  </div>
                </div>

                <div className="space-y-2">
                  <p className="font-medium text-gray-700">Learning Resources:</p>
                  <ul className="space-y-1">
                    {path.resources.map((resource, resIndex) => (
                      <li key={resIndex} className="flex items-start text-sm">
                        <BookOpen className="w-4 h-4 mr-2 mt-0.5 flex-shrink-0 text-gray-400" />
                        <span>{resource}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  const renderPriorityActions = () => {
    if (!detailed_analysis?.priority_actions?.length) return null;

    return (
      <div className="card">
        <h3 className="text-lg font-semibold mb-4 flex items-center text-primary-700">
          <Award className="w-5 h-5 mr-2" />
          Priority Actions
        </h3>

        <div className="space-y-3">
          {detailed_analysis.priority_actions.map((action, index) => (
            <div key={index} className={`border rounded-lg p-4 ${getPriorityColor(action.priority)}`}>
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <p className="font-medium mb-1">{action.action}</p>
                  <p className="text-sm text-gray-600">{action.reason}</p>
                </div>
                <span className="ml-4 text-xs font-medium uppercase px-2 py-1 rounded">
                  {action.priority}
                </span>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  const renderExperienceAnalysis = () => {
    if (!detailed_analysis?.experience_analysis) return null;

    const { experience_analysis } = detailed_analysis;

    return (
      <div className="card mb-6">
        <div className="flex items-center justify-between cursor-pointer" onClick={() => toggleSection('experience')}>
          <h3 className="text-lg font-semibold flex items-center text-primary-700">
            <Users className="w-5 h-5 mr-2" />
            Experience Analysis
          </h3>
          {expandedSections.experience ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
        </div>

        {expandedSections.experience && (
          <div className="mt-4 space-y-3">
            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <p className="text-sm text-gray-600">Your Experience</p>
                <p className="font-medium">
                  {experience_analysis.resume_experience ? `${experience_analysis.resume_experience} years` : 'Not specified'}
                </p>
                <p className="text-sm text-gray-500">Level: {experience_analysis.seniority_level}</p>
              </div>

              <div>
                <p className="text-sm text-gray-600">Required Experience</p>
                <p className="font-medium">
                  {experience_analysis.required_experience ? `${experience_analysis.required_experience} years` : 'Not specified'}
                </p>
                <p className="text-sm text-gray-500">Level: {experience_analysis.required_seniority}</p>
              </div>
            </div>

            {experience_analysis.gap_description && (
              <div className="p-3 bg-warning-50 rounded-lg">
                <p className="text-warning-800">{experience_analysis.gap_description}</p>
              </div>
            )}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Match Score Card */}
      <div className={`card ${getScoreBgColor(match_score)} border-2`}>
        <div className="text-center">
          <div className={`inline-flex items-center justify-center w-16 h-16 rounded-full ${getScoreBgColor(match_score)} mb-4`}>
            <div className={getScoreColor(match_score)}>
              {getScoreIcon(match_score)}
            </div>
          </div>

          <h2 className="text-3xl font-bold mb-2">
            <span className={getScoreColor(match_score)}>{match_score}%</span>
          </h2>

          <p className={`text-lg font-medium ${getScoreColor(match_score)}`}>
            {getScoreMessage(match_score)}
          </p>

          <div className="mt-4">
            <div className="w-full bg-gray-200 rounded-full h-3">
              <div 
                className={`h-3 rounded-full transition-all duration-1000 ease-out ${
                  match_score >= 80 ? 'bg-success-500' :
                  match_score >= 60 ? 'bg-warning-500' : 'bg-danger-500'
                }`}
                style={{ width: `${Math.min(match_score, 100)}%` }}
              />
            </div>
          </div>
        </div>
      </div>

      {/* Low Score Analysis - Only show for low scores */}
      {match_score < 70 && renderLowScoreAnalysis()}

      {/* Skills Analysis */}
      <div className="grid md:grid-cols-2 gap-6">
        {/* Matched Skills */}
        <div className="card">
          <h3 className="text-lg font-semibold mb-4 flex items-center text-success-700">
            <CheckCircle className="w-5 h-5 mr-2" />
            Matched Skills ({matched_skills.length})
          </h3>

          {matched_skills.length > 0 ? (
            <div className="flex flex-wrap gap-2">
              {matched_skills.map((skill, index) => (
                <span key={index} className="skill-matched">
                  {skill}
                </span>
              ))}
            </div>
          ) : (
            <p className="text-gray-500 italic">No matched skills found</p>
          )}
        </div>

        {/* Missing Skills */}
        <div className="card">
          <h3 className="text-lg font-semibold mb-4 flex items-center text-warning-700">
            <XCircle className="w-5 h-5 mr-2" />
            Missing Skills ({missing_skills.length})
          </h3>

          {missing_skills.length > 0 ? (
            <div className="flex flex-wrap gap-2">
              {missing_skills.map((skill, index) => (
                <span key={index} className="skill-missing">
                  {skill}
                </span>
              ))}
            </div>
          ) : (
            <p className="text-gray-500 italic">All required skills found!</p>
          )}
        </div>
      </div>

      {/* Skill Gap Analysis */}
      {renderSkillGapAnalysis()}

      {/* Experience Analysis */}
      {renderExperienceAnalysis()}

      {/* Improvement Recommendations */}
      {renderImprovementRecommendations()}

      {/* Learning Paths */}
      {renderLearningPaths()}

      {/* Priority Actions */}
      {renderPriorityActions()}

      {/* Detailed Skills Breakdown */}
      <div className="grid md:grid-cols-2 gap-6">
        {/* Resume Skills */}
        <div className="card">
          <h3 className="text-lg font-semibold mb-4 flex items-center text-primary-700">
            <Code className="w-5 h-5 mr-2" />
            Your Skills ({resume_skills.length})
          </h3>

          {resume_skills.length > 0 ? (
            <div className="flex flex-wrap gap-2 max-h-40 overflow-y-auto">
              {resume_skills.map((skill, index) => (
                <span key={index} className="skill-neutral">
                  {skill}
                </span>
              ))}
            </div>
          ) : (
            <p className="text-gray-500 italic">No skills detected</p>
          )}
        </div>

        {/* Job Requirements */}
        <div className="card">
          <h3 className="text-lg font-semibold mb-4 flex items-center text-primary-700">
            <Target className="w-5 h-5 mr-2" />
            Required Skills ({jd_skills.length})
          </h3>

          {jd_skills.length > 0 ? (
            <div className="flex flex-wrap gap-2 max-h-40 overflow-y-auto">
              {jd_skills.map((skill, index) => (
                <span key={index} className="skill-neutral">
                  {skill}
                </span>
              ))}
            </div>
          ) : (
            <p className="text-gray-500 italic">No skills detected in job description</p>
          )}
        </div>
      </div>

      {/* Score Breakdown */}
      <div className="card bg-gray-50">
        <h3 className="text-lg font-semibold mb-4">Score Breakdown</h3>

        <div className="space-y-3">
          <div className="flex justify-between items-center">
            <span className="text-gray-600">Skills Match</span>
            <span className="font-medium">
              {jd_skills.length > 0 
                ? Math.round((matched_skills.length / jd_skills.length) * 100) 
                : 0}%
            </span>
          </div>

          <div className="flex justify-between items-center">
            <span className="text-gray-600">Semantic Similarity</span>
            <span className="font-medium">{match_score}%</span>
          </div>

          <div className="flex justify-between items-center">
            <span className="text-gray-600">Skills Coverage</span>
            <span className="font-medium">
              {matched_skills.length} / {jd_skills.length} skills
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Results;
